// Time is monotonic OSC seconds, not GLED's repeating four-beat progression.
// Each native tile selects one pattern; the OSC runner crossfades scene opacities.
const STELLA_TAU: f32 = 6.28318530718;

fn soft_band(distance: f32, core: f32, width: f32) -> f32 {
    return 1.0 - smoothstep(core, width, abs(distance));
}

fn exhibition_pattern(kind: u32, edge_index: u32, local: f32,
                      rising: f32, height: f32, seconds: f32) -> vec3<f32> {
    let cyan = primary_color();
    let ember = secondary_color();
    let downward = edge_index >= 6u;
    let edge_in_tetra = edge_index % 6u;
    let tetra_color = select(cyan, ember, downward);

    switch kind {
        case 1u: {
            // Build twelve complete edges, hold the structure, then dissolve in order.
            let phase = seconds % 32.0;
            let order = f32(edge_index) * 1.1;
            let build = smoothstep(order, order + 0.8, phase);
            let dissolve = 1.0 - smoothstep(17.0 + order, 17.8 + order, phase);
            return tetra_color * (0.88 * build * dissolve);
        }
        case 2u: {
            // Reciprocal whole-tetra breathing: their summed brightness stays steady.
            let breath = 0.5 + 0.5 * sin(STELLA_TAU * seconds / 14.0);
            let level = select(breath, 1.0 - breath, downward);
            return tetra_color * (0.04 + 0.78 * level);
        }
        case 3u: {
            // All twelve heads share one fraction. Slopes travel physically low to high;
            // level bases retain their measured first-to-last electrical direction.
            let head = fract(seconds / 7.5) * 1.4 - 0.2;
            let chase = soft_band(rising - head, 0.045, 0.16);
            return tetra_color * (0.025 + 0.85 * chase);
        }
        case 4u: {
            // Opposing soft bands use actual sampled height, never projected edge order.
            let scan = 0.5 + 0.68 * sin(STELLA_TAU * seconds / 19.0);
            let cool = soft_band(height - scan, 0.035, 0.19);
            let warm = soft_band(height - (1.0 - scan), 0.025, 0.16);
            return cyan * (0.015 + 0.64 * cool) + ember * (0.015 + 0.54 * warm);
        }
        case 5u: {
            // mapping.md: T1 slopes E1(base->apex), E2/E6(apex->base);
            // T2 slopes E1/E5(apex->base), E4(base->apex).
            // All other edges join base corners reached by those slopes. Each base
            // receives a front at BOTH connected ends, and they meet in its middle.
            var apex_distance = 1.0 + min(local, 1.0 - local);
            switch edge_index {
                case 0u, 9u: { apex_distance = 1.0 - local; }
                case 1u, 5u, 6u, 10u: { apex_distance = local; }
                default: {}
            }
            // Equal physical run lengths define graph distance; SVG X is illustrative.
            let front = fract(seconds / 10.0) * 3.0 - 0.5;
            let wave = soft_band(apex_distance - front, 0.035, 0.17);
            let echo = soft_band(apex_distance - (front - 0.4), 0.025, 0.2);
            let echo_color = select(ember, cyan, downward);
            return tetra_color * (0.018 + 0.72 * wave) + echo_color * (0.26 * echo);
        }
        case 6u: {
            // T1 comets rise and T2 comets descend; base runs oppose electrically.
            // Staggered edge phases and long trailing tails distinguish this from chase.
            let travel = select(rising, 1.0 - rising, downward);
            let phase = fract(seconds / 9.0 - f32(edge_in_tetra) * 0.09);
            let head = phase * 2.1 - 0.35;
            let tail = exp(-max(head - travel, 0.0) / 0.2)
                     * (1.0 - smoothstep(0.0, 0.075, travel - head));
            let envelope = smoothstep(-0.35, -0.05, head)
                         * (1.0 - smoothstep(1.3, 1.75, head));
            return tetra_color * (0.02 + 0.83 * tail * envelope);
        }
        default: {
            // Quiet aurora: slow height-following color field with low edge contrast.
            let field = 0.5 + 0.5 * sin(STELLA_TAU * (height * 0.6 - seconds / 85.0)
                                    + f32(edge_index) * 0.24);
            let glow = 0.21 + 0.045 * sin(STELLA_TAU * seconds / 61.0
                                      + height * 2.0 + f32(edge_index) * 0.17);
            return mix(cyan, ember, 0.28 + 0.38 * field) * glow;
        }
    }
}

fn animation(coord: vec2<f32>, beat_progression: f32) -> vec3<f32> {
    let edge_index = min(uniforms.u32_0, 11u);
    // GLED shader coords are y-up: endpoints are (SVG x/400, 1 - SVG y/400).
    let start = vec2<f32>(uniforms.f32_0, uniforms.f32_1);
    let end = vec2<f32>(uniforms.f32_2, uniforms.f32_3);
    let axis = end - start;
    // Clamp texture-sampling boundary drift; guard even a coincident endpoint pair.
    let local = clamp(dot(coord - start, axis) / max(dot(axis, axis), 0.00000001), 0.0, 1.0);
    var rising = local;
    if abs(axis.y) > 0.00001 && axis.y < 0.0 {
        rising = 1.0 - local;
    }
    // Actual sampled SVG extrema are y=22..378, not ideal connector vertices.
    let height = clamp((coord.y - 0.055) / 0.89, 0.0, 1.0);
    let seconds = max(uniforms.f32_4, 0.0);
    let selected_mode = min(uniforms.u32_1, 6u) + 1u;
    return clamp(exhibition_pattern(selected_mode, edge_index, local, rising, height, seconds),
                 vec3<f32>(0.0), vec3<f32>(1.0));
}
